    if (!me.isMesh) return;
    me.castShadow = false; me.receiveShadow = false;
    const mat = me.material as THREE.MeshStandardMaterial;
    if (mat.name === 'paint') paint = mat;
    else if (mat.name === 'lamp_head') head = mat;
    else if (mat.name === 'lamp_tail') tail = mat;
