  const tb = t.clone(); drLampPatch(tb, 'drLampTail', M.tailNight, M.tailBrake);   // cùng khóa program: chỉ khác uniform
  const wheels: DrSource['wheels'] = [], z = new THREE.Vector3();
  for (const n of WHEELS) {
