    z.set(0, 0, 1).applyQuaternion(w.quaternion);
    wheels.push({ pos: w.position.clone(), quat: w.quaternion.clone(), sign: z.z > 0 ? -1 : 1 });   // bánh tiến: quanh +Z thế giới góc âm
