  scene.getObjectByName(WHEELS[0]).traverse((o) => { if ((o as THREE.Mesh).isMesh) wheelMeshes.push(o as THREE.Mesh); });
  if (!wheelMeshes.length) throw new Error('bánh không có lưới');
