/* ===== Bánh dùng chung: mỗi vật liệu một InstancedMesh, CAP chỗ ===== */
const A = new THREE.Matrix4(), B = new THREE.Matrix4(), Q = new THREE.Quaternion(), E = new THREE.Euler(), V1 = new THREE.Vector3(), UNIT = new THREE.Vector3(1, 1, 1), ZERO = new THREE.Matrix4().makeScale(0, 0, 0);
