      const im = new THREE.InstancedMesh(m.geometry, m.material, CAP);
      im.name = 'drive-wheels-' + (Array.isArray(m.material) ? '' : m.material.name);
      im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
